$(function(){let lastSentHeight=0;function sendHeight(){const height=Math.max(document.body.scrollHeight,document.body.offsetHeight,document.documentElement.clientHeight,document.documentElement.scrollHeight,document.documentElement.offsetHeight);if(Math.abs(height-lastSentHeight)>5){lastSentHeight=height;window.parent.postMessage({type:"resize",height:height},COURSES_BASE_URL||"*")}}setTimeout(sendHeight,100);function throttle(func,limit){let inThrottle;return function(){const args=arguments;const context=this;if(!inThrottle){func.apply(context,args);inThrottle=true;setTimeout(()=>inThrottle=false,limit)}}}window.addEventListener("resize",throttle(sendHeight,100));const observer=new MutationObserver(throttle(function(mutations){const relevantMutations=mutations.filter(mutation=>{return!(mutation.type==="attributes"&&mutation.attributeName==="style"&&mutation.target===document.body)});if(relevantMutations.length>0){sendHeight()}},100));observer.observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:["class","id","src"],characterData:true});setInterval(sendHeight,500)});